#include <string.h>

#include "FreeRTOS.h"
#include "task.h"
#include "platform.h"
#include "cache.h"

#include "board.h"
#include "memory_map.h"
#include "camera.h"
#include "work_mode.h"
#include "sync.h"
#include "cam_trig.h"
#include "laser.h"
#include "mm_table.h"
#include "settings.h"
#include "video.h"
#include "net_config.h"
#include "spi_flash.h"
#include "ethernet.h"
#include "watchdog.h"
#include "vmsp_protocol.h"
#include "vmsp_service.h"
#include "gev_regs.h"
#include "lcd_hud.h"
#include "gvcp.h"
#include "gvsp.h"
#include "arch/ethernetif.h"

#include "lwip/sockets.h"
#include "lwip/netif.h"

extern struct netif gnetif;                          // arch/sys_arch.c
// gev_xml.c (generated): the zipped GenApi XML and the FirstURL that points at it.
extern const char gev_first_url[];
extern const uint32_t gev_xml_addr;
extern const uint32_t gev_xml_len;
extern const uint8_t gev_xml_zip[];
// Linker (ae350-ddr.ld): the image as written to flash ends at the load address of _edata.
extern char __text_start, _edata, __text_lmastart;

#define GVCP_KEY            0x42U
#define GVCP_F_ACK          0x01U
#define GVCP_F_BCAST        0x10U    /* DISCOVERY / FORCEIP: the ack may be broadcast */

#define CMD_DISCOVERY       0x0002U
#define CMD_FORCEIP         0x0004U
#define CMD_PACKETRESEND    0x0040U
#define CMD_READREG         0x0080U
#define CMD_WRITEREG        0x0082U
#define CMD_READMEM         0x0084U
#define CMD_WRITEMEM        0x0086U
#define ACK_PENDING         0x0089U

#define ST_SUCCESS          0x0000U
#define ST_NOT_IMPLEMENTED  0x8001U
#define ST_INVALID_PARAM    0x8002U
#define ST_INVALID_ADDRESS  0x8003U
#define ST_WRITE_PROTECT    0x8004U
#define ST_BAD_ALIGNMENT    0x8005U
#define ST_ACCESS_DENIED    0x8006U
#define ST_BUSY             0x8007U
#define ST_INVALID_HEADER   0x800EU
#define ST_ERROR            0x8FFFU
// A register the XML has but this firmware does not serve yet: GEV 31.5 ("an optional register
// not supported"), not NOT_IMPLEMENTED, which is for commands (31.3) - viva-genicam takes that on
// a READREG as "READREG unsupported" and falls back to READMEM for the whole session.
#define ST_NOT_YET          ST_INVALID_ADDRESS

#define REG_MAX             135U     /* READREG addresses per command (576 B packet) */
#define WREG_MAX            67U      /* WRITEREG pairs per command */
#define MEM_MAX             536U     /* READMEM / WRITEMEM bytes per command */
#define ACK_MAX             (8U + 4U + MEM_MAX)
#define DISCOVERY_BYTES     248U     /* bootstrap 0x0000..0x00F7 */

// Bootstrap values (GEV ch. 27).
#define GEV_VERSION         0x00020002U   /* 2.2 */
#define DEVICE_MODE         0x80000002U   /* big-endian, transmitter, single link, ASCII */
#define NIC_LLA             0x4U
#define NIC_DHCP            0x2U
#define NIC_PIP             0x1U
#define CCP_EA              0x1U
#define CCP_CA              0x2U
#define CFG_PE              0x2U          /* GVCP configuration: PENDING_ACK enable */
#define CFG_HD              0x1U          /* heartbeat disable */
// GVCP capability 0x0934: user-defined name, serial number, heartbeat disable, link
// speed, CCP application port/IP, PENDING_ACK, WRITEMEM, concatenation. Not: events,
// PACKETRESEND, ACTION, extended status codes, manifest table.
#define GVCP_CAPS           (0x80000000U | 0x40000000U | 0x20000000U | 0x10000000U | \
                             0x08000000U | 0x20U | 0x04U | 0x02U | 0x01U)   /* + PACKETRESEND (GVSP, stage 3) */
#define GVSP_CAPS           0x80000000U   /* SCSPx; no legacy 16-bit block id (extended ID only) */
#define GVSP_CFG_BL         0x40000000U   /* 0x0960: 64-bit block id, always on */
#define HB_DEFAULT_MS       3000U
#define HB_MIN_MS           500U
// PendingTimeout: with PENDING_ACK enabled the longest wait before one is sent; without,
// the longest single command (camera setup 0x0112 or a flash write).
#define PENDING_MS          300U
#define WORST_MS            5000U
#define SLOW_MS             5000U    /* time_to_completion announced in a PENDING_ACK */

#define SC_COUNT            2U       /* stream channels: camera 0, camera 1 */
#define SC_BASE             0x0D00U
#define SCPS_MIN            576U
#define SCPS_MAX            8704U    /* the FPGA's largest frame, 8722 B with Ethernet header and FCS */
#define SCPS_DEFAULT        8704U

#define STR_VENDOR          "avtomatika-vektor"
#define STR_MODEL           "Vektor3D stereoVision"
#define STR_INFO            "Tang Mega 138K Pro, GW5AST-138B + AE350"

#define STATUS_WORDS        39U      /* 0x0300 answer, spec § 4.2 */
#define STATUS_TTL_MS       250U
#define MAXFPS_TTL_MS       2000U

#define FILE_BUF_BYTES      1024U
#define FILE_SETTINGS_SEC   0U       /* SettingsImage = the settings partition */

typedef struct {
    struct sockaddr_in src;
    uint32_t ip;                     /* sender, host order */
    uint16_t port;
    uint16_t req_id;
    bool     ack;                    /* the sender asked for an acknowledge */
} req_t;

static struct {
    int      fd;
    // control channel privilege (GEV ch. 10)
    uint32_t ccp;                    /* 0, CCP_EA or CCP_CA */
    uint32_t app_ip;                 /* primary application, host order */
    uint16_t app_port;
    uint32_t last_rx;                /* ms of its last command */
    uint32_t hb_ms;
    uint32_t gvcp_cfg;
    uint16_t last_req;               /* its last req_id and the ack sent (R-051) */
    uint16_t last_len;
    uint8_t  last_ack[ACK_MAX];
    bool     reset_req;
    // bootstrap state
    char     vendor[32], model[32], version[32], info[48], serial[16], fw_ver[32];
    char     user[NET_NAME_MAX + 1]; /* 16 B register; [16] stays 0 */
    bool     user_dirty;
    net_config_t pers;               /* persistent address as written, stored when valid */
    bool     pers_partial;            /* pers holds a set written in part, not valid yet */
    uint32_t ts_hi, ts_lo;
    uint32_t mcp, mcda, mctt, mcrc;
    uint32_t scp[SC_COUNT], scps[SC_COUNT], scpd[SC_COUNT], scda[SC_COUNT];
    uint32_t fw_crc, fw_len, fpga_id;
    // manufacturer state kept here until stage 3 gives it meaning
    uint32_t tl_locked, chunk_mode, chunk_en[4], event_en[4], acq_mode, acq_count;
    uint32_t scan_type[2], lines[2], out_mode[2], comp_en[2][4], delivery[2], acked[2][2];
    uint32_t user_set;
    uint8_t  mac_set[6];             /* DeviceMACAddressSet*: the address to store, valid when mac_dirty */
    bool     mac_dirty;
    uint8_t  acq_cams;               /* sources AcquisitionStart started */
    uint32_t gen_rate, gen_count, gen_width, gen_inv;
    bool     gen_loaded;
    bool     lf_ack[2];              /* the FPGA confirmed the last finder setting */
    // caches of slow reads
    uint32_t st[STATUS_WORDS];
    uint32_t st_ms;
    bool     st_valid;
    uint32_t max_fps[2], mf_ms[2];
    bool     mf_valid[2];
} s;

// FileAccessControl (SFNC): one open file at a time.
static struct {
    uint32_t sel, op, mode, off, len, status, result, save;
    bool     open;
    uint32_t open_sel, open_mode;
    uint8_t  hdr[MM_HDR_BYTES];      /* MmTable: the 0x0134 commit body */
    uint8_t  img[4U + SETTINGS_IMAGE_MAX];   /* calibration (72 B) or a settings image */
    uint32_t img_len;
    uint8_t  buf[FILE_BUF_BYTES];
} f;

static uint8_t s_vout[300];          /* VMSP answer body (VCP_REPLY_MAX) */
static uint8_t s_vbody[8U + FILE_BUF_BYTES];

// ---- helpers -------------------------------------------------------------------

static uint16_t rd16(const uint8_t *p) { return (uint16_t)((p[0] << 8) | p[1]); }
static uint32_t rd32(const uint8_t *p)
{
    return ((uint32_t)p[0] << 24) | ((uint32_t)p[1] << 16) | ((uint32_t)p[2] << 8) | p[3];
}
static void wr16(uint8_t *p, uint16_t v) { p[0] = (uint8_t)(v >> 8); p[1] = (uint8_t)v; }
static void wr32(uint8_t *p, uint32_t v)
{
    p[0] = (uint8_t)(v >> 24); p[1] = (uint8_t)(v >> 16); p[2] = (uint8_t)(v >> 8); p[3] = (uint8_t)v;
}

static uint32_t now_ms(void)
{
    return (uint32_t)(xTaskGetTickCount() * portTICK_PERIOD_MS);
}

static uint32_t ip_u32(const uint8_t a[4])
{
    return ((uint32_t)a[0] << 24) | ((uint32_t)a[1] << 16) | ((uint32_t)a[2] << 8) | a[3];
}

static void u32_ip(uint8_t a[4], uint32_t v)
{
    a[0] = (uint8_t)(v >> 24); a[1] = (uint8_t)(v >> 16); a[2] = (uint8_t)(v >> 8); a[3] = (uint8_t)v;
}

// Four bytes of a NUL-padded string register as a big-endian word.
static uint32_t str_word(const char *str, size_t cap, uint32_t off)
{
    size_t n = strnlen(str, cap);
    uint32_t v = 0, i;

    for (i = 0; i < 4U; ++i)
        v = (v << 8) | ((off + i < n) ? (uint8_t)str[off + i] : 0U);
    return v;
}

static void send_to(const struct sockaddr_in *dst, const uint8_t *p, size_t n)
{
    (void)lwip_sendto(s.fd, p, n, 0, (const struct sockaddr *)dst, sizeof(*dst));
}

static bool is_primary(const req_t *r)
{
    return s.ccp != 0U && r->ip == s.app_ip && r->port == s.app_port;
}

// A command about to outlast PendingTimeout: tell the application (GEV 16.8), when it
// enabled PENDING_ACK. The heartbeat restarts when the command ends (handle()).
static void pending(const req_t *r)
{
    uint8_t a[12];

    if (!r->ack || !(s.gvcp_cfg & CFG_PE)) return;
    wr16(a, ST_SUCCESS);
    wr16(a + 2, ACK_PENDING);
    wr16(a + 4, 4);
    wr16(a + 6, r->req_id);
    wr16(a + 8, 0);
    wr16(a + 10, SLOW_MS);
    send_to(&r->src, a, sizeof(a));
}

// DeviceMACAddressSet*: starts from the running address, so a half written alone keeps the other.
static void mac_set_load(void)
{
    if (s.mac_dirty) return;
    memcpy(s.mac_set, gnetif.hwaddr, 6);
    s.mac_dirty = true;
}

static uint16_t vmsp_status(uint8_t st)
{
    switch (st) {
    case 0x00: return ST_SUCCESS;
    case 0x02: return ST_BUSY;                  /* VCP_ST_BUSY */
    case 0x09:                                  /* VCP_ST_DENIED: value refused, WORK lock */
    case 0x0C: return ST_INVALID_PARAM;         /* VCP_ST_UNSUPPORTED */
    default:   return ST_ERROR;                 /* hardware error, timeout, length */
    }
}

// A VMSP control opcode in-process; the first answer byte is its status.
static uint16_t vcall(uint16_t op, const uint8_t *body, uint32_t len)
{
    int n = vmsp_call(op, body, len, s_vout, sizeof(s_vout));
    return (n < 1) ? ST_ERROR : vmsp_status(s_vout[0]);
}

// 0x0300 answer, cached briefly: one READREG of many counters costs one I2C round.
static bool status_words(void)
{
    uint32_t i;
    int n;

    if (s.st_valid && now_ms() - s.st_ms < STATUS_TTL_MS) return true;
    n = vmsp_call(0x0300, NULL, 0, s_vout, sizeof(s_vout));
    if (n < (int)(STATUS_WORDS * 4U)) return false;
    for (i = 0; i < STATUS_WORDS; ++i) s.st[i] = rd32(s_vout + 4U * i);
    s.st_ms = now_ms();
    s.st_valid = true;
    return true;
}

// Highest frame rate of the current ROI (0x0122 words 28..31, read from the sensor).
static uint16_t max_fps(uint8_t c, uint32_t *v)
{
    uint8_t b[2] = { 0, c };
    int n;

    if (!s.mf_valid[c] || now_ms() - s.mf_ms[c] >= MAXFPS_TTL_MS) {
        n = vmsp_call(0x0122, b, sizeof(b), s_vout, sizeof(s_vout));
        if (n < 32 || s_vout[0] != 0) return (n < 1) ? ST_ERROR : vmsp_status(s_vout[0]);
        s.max_fps[c] = rd32(s_vout + 28);
        s.mf_ms[c] = now_ms();
        s.mf_valid[c] = true;
    }
    *v = s.max_fps[c];
    return ST_SUCCESS;
}

// Stream channel x's registers to the GVSP scheduler (gvsp.c).
static void sc_push(uint32_t x)
{
    gvsp_channel_set((uint8_t)x, s.scda[x], (uint16_t)(s.scp[x] & 0xFFFFU), (uint16_t)(s.scps[x] & 0xFFFFU),
                     s.scpd[x]);
}

static void close_channels(void)
{
    uint32_t i;

    gvsp_stop((1U << SC_COUNT) - 1U);
    for (i = 0; i < SC_COUNT; ++i) {
        s.scp[i] = 0;
        sc_push(i);
    }
    s.acq_cams = 0;                  /* streams stop; a free-running sensor keeps writing its ring */
    s.mcp = 0;
}

static void release(const char *why)
{
    printf("[GVCP] control released (%s): %u.%u.%u.%u:%u\r\n", why,
           (unsigned)(s.app_ip >> 24), (unsigned)((s.app_ip >> 16) & 0xFFU),
           (unsigned)((s.app_ip >> 8) & 0xFFU), (unsigned)(s.app_ip & 0xFFU), (unsigned)s.app_port);
    s.ccp = 0;
    s.app_ip = 0;
    s.app_port = 0;
    s.gvcp_cfg = 0;                  /* factory default once the channel is closed (CR-571s) */
    s.tl_locked = 0;
    s.last_len = 0;
    close_channels();
}

// ---- identity --------------------------------------------------------------------

static void identity_init(void)
{
    uint32_t lma = (uint32_t)(uintptr_t)&__text_lmastart;
    const uint8_t *m = gnetif.hwaddr;

    // CRC-32 of the image as it lies in flash: the same number as the .bin's CRC in
    // docs/WORKFLOWS.md § 7. The boot window is cacheable but never dirty.
    s.fw_len = lma + (uint32_t)(&_edata - &__text_start);
    ae350_dcache_flush_all();
    s.fw_crc = vmsp_crc32((const uint8_t *)SPI_FLASH_WINDOW(0x00600000U), s.fw_len);
    printf("[GVCP] firmware image %u B, CRC-32 %08X\r\n", (unsigned)s.fw_len, (unsigned)s.fw_crc);

    snprintf(s.vendor, sizeof(s.vendor), "%s", STR_VENDOR);
    snprintf(s.model, sizeof(s.model), "%s", STR_MODEL);
    // Bitstream id: CRC-32 of its RTL sources (fpga/src/build_id.v); 0 on older bitstreams.
    s.fpga_id = spi_flash_build_id();
    if (s.fpga_id != 0U)
        snprintf(s.version, sizeof(s.version), "fw %08X fpga %08X", (unsigned)s.fw_crc, (unsigned)s.fpga_id);
    else
        snprintf(s.version, sizeof(s.version), "fw %08X fpga unknown", (unsigned)s.fw_crc);
    snprintf(s.info, sizeof(s.info), "%s", STR_INFO);
    // flash_ctl.v refuses the unique-ID command (RDUID), so the serial is the MAC.
    snprintf(s.serial, sizeof(s.serial), "%02X%02X%02X%02X%02X%02X", m[0], m[1], m[2], m[3], m[4], m[5]);
    // No build date: the build stays byte-for-byte reproducible (WORKFLOWS § 4).
    snprintf(s.fw_ver, sizeof(s.fw_ver), "%08X (CRC-32, %u B)", (unsigned)s.fw_crc, (unsigned)s.fw_len);
    net_name_get(s.user);
}

// ---- bootstrap registers (GEV ch. 27) ---------------------------------------------

// The persistent address as stored now - VMSP 0x0003 and the console store it too, so it is read
// again every time (a copy kept from boot showed a stale address and wrote it back over the new one
// on the next GVCP write, 28.10.2026). Only a set written in part keeps its registers until whole.
static void pers_load(void)
{
    if (!s.pers_partial) (void)net_config_stored(&s.pers);
}

static uint32_t link_mbps(void)
{
    uint32_t mode = DEV_ETHERNET->ETH_MODE;    /* the MAC follows PHYSR (ethernetif.c), no MIIM here */
    return (mode == ETH_FULL_DUPLEX_1000M) ? 1000U : (mode == ETH_FULL_DUPLEX_100M) ? 100U : 10U;
}

static uint16_t boot_read(uint32_t a, uint32_t *v)
{
    net_config_t c;

    if (a >= 0x0048U && a < 0x0068U) { *v = str_word(s.vendor, 32, a - 0x0048U); return ST_SUCCESS; }
    if (a >= 0x0068U && a < 0x0088U) { *v = str_word(s.model, 32, a - 0x0068U); return ST_SUCCESS; }
    if (a >= 0x0088U && a < 0x00A8U) { *v = str_word(s.version, 32, a - 0x0088U); return ST_SUCCESS; }
    if (a >= 0x00A8U && a < 0x00D8U) { *v = str_word(s.info, 48, a - 0x00A8U); return ST_SUCCESS; }
    if (a >= 0x00D8U && a < 0x00E8U) { *v = str_word(s.serial, 16, a - 0x00D8U); return ST_SUCCESS; }
    if (a >= 0x00E8U && a < 0x00F8U) { *v = str_word(s.user, 16, a - 0x00E8U); return ST_SUCCESS; }
    if (a >= 0x0200U && a < 0x0400U) { *v = str_word(gev_first_url, 512, a - 0x0200U); return ST_SUCCESS; }
    if (a >= 0x0400U && a < 0x0600U) { *v = 0; return ST_SUCCESS; }          /* Second URL: none */
    if (a >= SC_BASE && a < SC_BASE + 0x40U * SC_COUNT) {
        uint32_t x = (a - SC_BASE) / 0x40U, o = (a - SC_BASE) % 0x40U;
        switch (o) {
        case 0x00: *v = s.scp[x] & 0xFFFFU; return ST_SUCCESS;     /* transmitter, interface 0 */
        case 0x04: *v = s.scps[x] & 0x4000FFFFU; return ST_SUCCESS; /* fire-test bit reads 0 */
        case 0x08: *v = s.scpd[x]; return ST_SUCCESS;
        case 0x18: *v = s.scda[x]; return ST_SUCCESS;
        case 0x1C: *v = GVSP_SRC_PORT; return ST_SUCCESS;         /* GevSCSP */
        default:   return ST_INVALID_ADDRESS;
        }
    }
    switch (a) {
    case 0x0000: *v = GEV_VERSION; return ST_SUCCESS;
    case 0x0004: *v = DEVICE_MODE; return ST_SUCCESS;
    case 0x0008: *v = ((uint32_t)gnetif.hwaddr[0] << 8) | gnetif.hwaddr[1]; return ST_SUCCESS;
    case 0x000C: *v = ((uint32_t)gnetif.hwaddr[2] << 24) | ((uint32_t)gnetif.hwaddr[3] << 16) |
                      ((uint32_t)gnetif.hwaddr[4] << 8) | gnetif.hwaddr[5]; return ST_SUCCESS;
    case 0x0010: *v = NIC_LLA | NIC_DHCP | NIC_PIP; return ST_SUCCESS;
    case 0x0014: *v = NIC_LLA | net_ipcfg_get(); return ST_SUCCESS;    /* NET_IPCFG_* = GEV bits P, D */
    case 0x0024: net_config_current(&c); *v = ip_u32(c.ip); return ST_SUCCESS;
    case 0x0034: net_config_current(&c); *v = ip_u32(c.mask); return ST_SUCCESS;
    case 0x0044: net_config_current(&c); *v = ip_u32(c.gw); return ST_SUCCESS;
    case 0x0600: *v = 1; return ST_SUCCESS;                        /* network interfaces */
    case 0x064C: pers_load(); *v = ip_u32(s.pers.ip); return ST_SUCCESS;
    case 0x065C: pers_load(); *v = ip_u32(s.pers.mask); return ST_SUCCESS;
    case 0x066C: pers_load(); *v = ip_u32(s.pers.gw); return ST_SUCCESS;
    case 0x0670: *v = link_mbps(); return ST_SUCCESS;
    case 0x0900: *v = 1; return ST_SUCCESS;                        /* message channels */
    case 0x0904: *v = SC_COUNT; return ST_SUCCESS;                 /* stream channels */
    case 0x0910: *v = 1; return ST_SUCCESS;                        /* active links */
    case 0x092C: *v = GVSP_CAPS; return ST_SUCCESS;
    case 0x0960: *v = GVSP_CFG_BL; return ST_SUCCESS;              /* GVSP configuration */
    case 0x0930: *v = 0; return ST_SUCCESS;                        /* message channel capability */
    case 0x0934: *v = GVCP_CAPS; return ST_SUCCESS;
    case 0x0938: *v = s.hb_ms; return ST_SUCCESS;
    case 0x093C: *v = 0; return ST_SUCCESS;                        /* tick 100 MHz (PLMT, = FPGA lane clock) */
    case 0x0940: *v = 100000000U; return ST_SUCCESS;
    case 0x0948: *v = s.ts_hi; return ST_SUCCESS;
    case 0x094C: *v = s.ts_lo; return ST_SUCCESS;
    case 0x0954: *v = s.gvcp_cfg; return ST_SUCCESS;
    case 0x0958: *v = (s.gvcp_cfg & CFG_PE) ? PENDING_MS : WORST_MS; return ST_SUCCESS;
    case 0x0964: *v = 1; return ST_SUCCESS;                        /* single link only */
    case 0x0968: *v = 0; return ST_SUCCESS;                        /* single link */
    case 0x0A00: *v = s.ccp; return ST_SUCCESS;
    case 0x0A04: *v = s.app_port; return ST_SUCCESS;
    case 0x0A14: *v = s.app_ip; return ST_SUCCESS;
    case 0x0B00: *v = s.mcp & 0xFFFFU; return ST_SUCCESS;
    case 0x0B10: *v = s.mcda; return ST_SUCCESS;
    case 0x0B14: *v = s.mctt; return ST_SUCCESS;
    case 0x0B18: *v = s.mcrc; return ST_SUCCESS;
    default:     return ST_INVALID_ADDRESS;
    }
}

// CCP (GEV 27.46, table 27-2): exclusive or control access, no switchover.
static uint16_t ccp_write(const req_t *r, uint32_t v)
{
    uint32_t want = (v & CCP_EA) ? CCP_EA : (v & CCP_CA) ? CCP_CA : 0U;

    if (s.ccp == 0U) {
        if (want == 0U) return ST_SUCCESS;
        s.ccp = want;
        s.app_ip = r->ip;
        s.app_port = r->port;
        s.last_rx = now_ms();
        s.last_len = 0;
        printf("[GVCP] %s access granted to %u.%u.%u.%u:%u\r\n", (want == CCP_EA) ? "exclusive" : "control",
               (unsigned)(r->ip >> 24), (unsigned)((r->ip >> 16) & 0xFFU), (unsigned)((r->ip >> 8) & 0xFFU),
               (unsigned)(r->ip & 0xFFU), (unsigned)r->port);
        return ST_SUCCESS;
    }
    if (!is_primary(r)) return ST_ACCESS_DENIED;
    if (want == 0U) release("by the application");
    else s.ccp = want;
    return ST_SUCCESS;
}

static uint16_t boot_write(const req_t *r, uint32_t a, uint32_t v)
{
    if (a >= 0x00E8U && a < 0x00F8U) {          /* user-defined name, stored when the command ends */
        uint32_t o = a - 0x00E8U, i;
        uint8_t b[4];
        wr32(b, v);
        for (i = 0; i < 4U; ++i)
            if (b[i] >= 0x80U) return ST_INVALID_PARAM;            /* ASCII (device mode charset) */
        memcpy(s.user + o, b, 4);
        s.user_dirty = true;
        return ST_SUCCESS;
    }
    if (a >= SC_BASE && a < SC_BASE + 0x40U * SC_COUNT) {
        uint32_t x = (a - SC_BASE) / 0x40U, o = (a - SC_BASE) % 0x40U, n;
        switch (o) {
        case 0x00:                                                 /* host port: opens / closes */
            if (gvsp_running((uint8_t)x) && (v & 0xFFFFU) != 0U) return ST_BUSY;   /* R-586 */
            s.scp[x] = v & 0xFFFFU;
            sc_push(x);
            return ST_SUCCESS;
        case 0x04:                                                 /* fire test packet: no GVSP yet */
            n = v & 0xFFFFU;
            n = (n < SCPS_MIN) ? SCPS_MIN : (n > SCPS_MAX) ? SCPS_MAX : (n & ~3U);
            s.scps[x] = (v & 0x40000000U) | n;
            sc_push(x);
            return ST_SUCCESS;
        case 0x08: s.scpd[x] = v; sc_push(x); return ST_SUCCESS;
        case 0x18: s.scda[x] = v; sc_push(x); return ST_SUCCESS;
        case 0x1C: return ST_WRITE_PROTECT;
        default:   return ST_INVALID_ADDRESS;
        }
    }
    switch (a) {
    case 0x0014:                                 /* stored; applies at the next boot or FORCEIP 0 */
        if ((v & (NIC_DHCP | NIC_PIP)) == net_ipcfg_get()) return ST_SUCCESS;
        pending(r);
        return (net_ipcfg_set(v & (NIC_DHCP | NIC_PIP)) == 0) ? ST_SUCCESS : ST_ERROR;
    case 0x064C: case 0x065C: case 0x066C:
        // Persistent address: kept as written, stored once the three make a valid set; it
        // applies at the next boot. Reads show what was written.
        pers_load();
        u32_ip((a == 0x064CU) ? s.pers.ip : (a == 0x065CU) ? s.pers.mask : s.pers.gw, v);
        s.pers_partial = !net_config_valid(&s.pers);
        if (!s.pers_partial) {
            pending(r);
            if (net_config_store(&s.pers) != 0) return ST_ERROR;
        }
        return ST_SUCCESS;
    case 0x0938: s.hb_ms = (v < HB_MIN_MS) ? HB_MIN_MS : v; return ST_SUCCESS;
    case 0x0944:
        if (v & 0x1U) return ST_INVALID_PARAM;          /* reset: the PLMT is FreeRTOS's tick, never */
        if (v & 0x2U) {
            uint32_t hi, lo;
            do {
                hi = DEV_PLMT->MTIME[1];
                lo = DEV_PLMT->MTIME[0];
            } while (hi != DEV_PLMT->MTIME[1]);
            s.ts_hi = hi;
            s.ts_lo = lo;
        }
        return ST_SUCCESS;
    case 0x0954: s.gvcp_cfg = v & (CFG_PE | CFG_HD); return ST_SUCCESS;
    case 0x0968: return (v == 0U) ? ST_SUCCESS : ST_INVALID_PARAM;
    case 0x0960: return (v & GVSP_CFG_BL) ? ST_SUCCESS : ST_INVALID_PARAM;   /* extended ID cannot be turned off */
    case 0x0A00: return ccp_write(r, v);
    case 0x0B00: s.mcp = v & 0xFFFFU; return ST_SUCCESS;
    case 0x0B10: s.mcda = v; return ST_SUCCESS;
    case 0x0B14: s.mctt = v; return ST_SUCCESS;
    case 0x0B18: s.mcrc = v; return ST_SUCCESS;
    default: {
        uint32_t dummy;
        return (boot_read(a, &dummy) == ST_INVALID_ADDRESS) ? ST_INVALID_ADDRESS : ST_WRITE_PROTECT;
    }
    }
}

static uint16_t user_flush(const req_t *r)
{
    if (!s.user_dirty) return ST_SUCCESS;
    s.user_dirty = false;
    pending(r);
    if (net_name_store(s.user) != 0) {
        net_name_get(s.user);                      /* what the store really holds */
        return ST_ERROR;
    }
    return ST_SUCCESS;
}

// ---- manufacturer registers: sync block, laser, generator --------------------------

// 0x0142 with the current shadow and one field changed.
static uint16_t sync_control(uint32_t ctrl, uint32_t filter, uint32_t pol)
{
    uint8_t b[12];

    b[0] = (ctrl & SYNC_CTRL_ENABLE) ? 1U : 0U;
    b[1] = (uint8_t)((ctrl & SYNC_CTRL_SRC_MASK) >> SYNC_CTRL_SRC_SHIFT);
    b[2] = (ctrl & SYNC_CTRL_LASER_EN) ? 1U : 0U;
    b[3] = (ctrl & SYNC_CTRL_EXT_FALL) ? 1U : 0U;
    wr32(b + 4, filter);
    wr32(b + 8, pol);
    return vcall(0x0142, b, sizeof(b));
}

static uint16_t sync_ctrl_set(uint32_t clear, uint32_t set)
{
    return sync_control((sync_get(SYNC_W_CTRL) & ~clear) | set, sync_get(SYNC_W_EXT_FILTER),
                        sync_get(SYNC_W_POLARITY));
}

static uint16_t sync_pol_set(uint32_t bit, uint32_t on)
{
    uint32_t pol = sync_get(SYNC_W_POLARITY) & ~bit;
    return sync_control(sync_get(SYNC_W_CTRL), sync_get(SYNC_W_EXT_FILTER), on ? (pol | bit) : pol);
}

// 0x0140: channel 0/1 = camera trigger, 2 = laser; times in lane ticks (10 ns).
static uint16_t sync_channel(uint8_t ch, uint32_t mode, uint32_t delay_t, uint32_t width_t)
{
    uint8_t b[12];

    if (delay_t > 0xFFFFFFFFU / 10U || width_t > 0xFFFFFFFFU / 10U || mode > 3U) return ST_INVALID_PARAM;
    memset(b, 0, sizeof(b));
    b[0] = ch;
    b[1] = (uint8_t)mode;
    wr32(b + 4, delay_t * 10U);
    wr32(b + 8, width_t * 10U);
    return vcall(0x0140, b, sizeof(b));
}

static uint32_t w_delay(uint8_t ch) { return (ch == 0) ? SYNC_W_CAM0_DELAY : (ch == 1) ? SYNC_W_CAM1_DELAY : SYNC_W_LASER_DELAY; }
static uint32_t w_width(uint8_t ch) { return (ch == 0) ? SYNC_W_CAM0_WIDTH : (ch == 1) ? SYNC_W_CAM1_WIDTH : SYNC_W_LASER_WIDTH; }

static void gen_load(void)
{
    if (!s.gen_loaded) {
        cam_trig_get(&s.gen_rate, &s.gen_count, &s.gen_width);
        s.gen_loaded = true;
    }
}

// 0x0302 with the generator shadow; stop = flag 2.
static uint16_t gen_apply(bool stop)
{
    uint8_t b[12];

    wr32(b, s.gen_rate);
    wr16(b + 4, (uint16_t)s.gen_count);
    wr16(b + 6, (uint16_t)((s.gen_inv ? 1U : 0U) | (stop ? 2U : 0U)));
    wr32(b + 8, s.gen_width);
    return vcall(0x0302, b, sizeof(b));
}

// ---- manufacturer registers: camera (0x0112 / 0x0120 paths) -------------------------

// 0x0112 from the cache with one field changed: one register write = one camera
// reconfiguration (the sensor restarts), so clients set the ROI before streaming.
// free_run: byte 3 bit 0 of 0x0112 - a stream-mode sensor starts capturing (AcquisitionStart).
static uint16_t cam_cfg_f(const req_t *r, uint8_t c, const camera_params_t *p, bool free_run)
{
    uint8_t b[24];

    b[0] = c;
    b[1] = p->trg_mode ? 1U : 0U;               /* 1 = hardware trigger armed */
    b[2] = p->testpat & 1U;
    b[3] = free_run ? 1U : 0U;
    wr32(b + 4, p->exp);
    wr16(b + 8, (uint16_t)p->gain);
    wr16(b + 10, (uint16_t)((p->fps > 0xFFFFU) ? 0U : p->fps));
    wr16(b + 12, (uint16_t)p->roi_w);
    wr16(b + 14, (uint16_t)p->roi_h);
    wr16(b + 16, (uint16_t)p->offset_x);
    wr16(b + 18, (uint16_t)p->offset_y);
    wr32(b + 20, p->fps);
    pending(r);
    s.mf_valid[c] = false;
    return vcall(0x0112, b, sizeof(b));
}

static uint16_t cam_cfg(const req_t *r, uint8_t c, const camera_params_t *p)
{
    return cam_cfg_f(r, c, p, (s.acq_cams >> c) & 1U);  /* a running free-run camera stays running */
}

// AcquisitionStart / Stop: the frames (DeviceScanType Areascan) of every source whose stream
// channel is open go out as GVSP blocks (gvsp.c). A source not in trigger mode is set free-running
// (0x0112 flag); a board in STANDBY goes to SERVICE first (0x0110), as the capture tools do.
static uint32_t payload_size(uint8_t c);
static uint8_t comps_of(uint8_t c);

static uint16_t acquisition(const req_t *r, bool start)
{
    camera_params_t p;
    uint8_t mask = 0, c, mode[2] = { 0, 2 };   /* 0x0110 body: u16 SERVICE */
    uint16_t st = ST_SUCCESS;

    if (!start) {
        gvsp_stop((1U << SC_COUNT) - 1U);
        for (c = 0; c < SC_COUNT; ++c) {
            if (!((s.acq_cams >> c) & 1U)) continue;
            s.acq_cams &= (uint8_t)~(1U << c);
            (void)camera_cached_params(c, &p);
            if (p.trg_mode == 0U && st == ST_SUCCESS) st = cam_cfg_f(r, c, &p, false);   /* capture off */
        }
        return st;
    }
    for (c = 0; c < SC_COUNT; ++c) {
        if ((s.scp[c] & 0xFFFFU) == 0U) continue;
        if (s.scan_type[c] == GEV_SRC_OFF_DEVICE_SCAN_TYPE_LINESCAN3D && payload_size(c) == 0U) continue;
        gvsp_profile_set(c, s.scan_type[c] == GEV_SRC_OFF_DEVICE_SCAN_TYPE_LINESCAN3D, (uint8_t)s.lines[c],
                         comps_of(c), s.out_mode[c] != 0U, s.chunk_mode != 0U);
        mask |= 1U << c;
    }
    if (mask == 0U) return ST_INVALID_PARAM;    /* no open stream channel with something to send */
    if (work_mode_get() == WORK_MODE_STANDBY && (st = vcall(0x0110, mode, sizeof(mode))) != ST_SUCCESS) return st;
    for (c = 0; c < SC_COUNT && st == ST_SUCCESS; ++c) {
        if (!((mask >> c) & 1U)) continue;
        (void)camera_cached_params(c, &p);
        s.acq_cams |= (uint8_t)(1U << c);
        if (p.trg_mode == 0U) st = cam_cfg_f(r, c, &p, true);
    }
    if (st == ST_SUCCESS) gvsp_start(mask);
    return st;
}

// Region0 Height: one ROI height for both cameras (GEOM goes with camera 0, 0x0112).
static uint16_t height_set(const req_t *r, uint32_t v)
{
    camera_params_t p;
    uint16_t st = ST_SUCCESS;
    uint8_t c;

    if (v < 64U || v > VIDEO_FRAME_HEIGHT || (v & 3U)) return ST_INVALID_PARAM;
    for (c = 0; c < VIDEO_CAM_COUNT && st == ST_SUCCESS; ++c) {
        if (c > 0 && !camera_connected(c)) continue;
        (void)camera_cached_params(c, &p);
        if (p.offset_y + v > VIDEO_FRAME_HEIGHT) return ST_INVALID_PARAM;
        p.roi_h = v;
        st = cam_cfg(r, c, &p);
    }
    return st;
}

static uint16_t exposure_set(uint8_t c, uint32_t exp_us, int32_t gain)
{
    uint8_t b[8];

    wr16(b, c);
    wr32(b + 2, exp_us);
    if (gain >= 0) wr16(b + 6, (uint16_t)gain);
    s.mf_valid[c] = false;
    return vcall(0x0120, b, (gain >= 0) ? 8U : 6U);
}

// 0x0150 with this camera's setting and one field changed.
static uint16_t finder_set(uint8_t c, uint32_t off, uint32_t v)
{
    laser_cfg_t lc;
    uint8_t b[14];
    uint16_t st;

    laser_cfg_get(c, &lc);
    switch (off) {
    case GEV_SRC_OFF_LASER_FINDER_THRESHOLD:    if (v > 0xFFU) return ST_INVALID_PARAM; lc.thresh = (uint8_t)v; break;
    case GEV_SRC_OFF_LASER_FINDER_FLOOR:        if (v > 0xFFU) return ST_INVALID_PARAM; lc.offset = (uint8_t)v; break;
    case GEV_SRC_OFF_LASER_FINDER_GAP:          if (v > 0xFFU) return ST_INVALID_PARAM; lc.gap = (uint8_t)v; break;
    case GEV_SRC_OFF_LASER_FINDER_WINDOW_START: if (v > 0xFFFFU) return ST_INVALID_PARAM; lc.win_lo = (uint16_t)v; break;
    case GEV_SRC_OFF_LASER_FINDER_WINDOW_END:   if (v > 0xFFFFU) return ST_INVALID_PARAM; lc.win_hi = (uint16_t)v; break;
    case GEV_SRC_OFF_LASER_FINDER_MIN_SUM:      if (v > 0xFFFFU) return ST_INVALID_PARAM; lc.min_sum = (uint16_t)v; break;
    default:                                    if (v > 0xFFFFU) return ST_INVALID_PARAM; lc.width_max = (uint16_t)v; break;
    }
    b[0] = c;
    b[1] = lc.offset;
    b[2] = lc.axis;
    b[3] = lc.thresh;
    b[4] = lc.gap;
    b[5] = lc.flags;
    wr16(b + 6, lc.win_lo);
    wr16(b + 8, lc.win_hi);
    wr16(b + 10, lc.min_sum);
    wr16(b + 12, lc.width_max);
    st = vcall(0x0150, b, sizeof(b));
    s.lf_ack[c] = (st == ST_SUCCESS) && (s_vout[15] & 4U);
    return st;
}

// Profile components enabled on source c (ComponentSelector 1 Range, 2 Reflectance, 3 Confidence).
static uint8_t comps_of(uint8_t c)
{
    return (uint8_t)((s.comp_en[c][1] ? GVSP_COMP_RANGE : 0U) | (s.comp_en[c][2] ? GVSP_COMP_REFLECTANCE : 0U) |
                     (s.comp_en[c][3] ? GVSP_COMP_CONFIDENCE : 0U));
}

static uint32_t payload_size(uint8_t c)
{
    camera_params_t p;

    (void)camera_cached_params(c, &p);
    if (s.scan_type[c] == GEV_SRC_OFF_DEVICE_SCAN_TYPE_AREASCAN) return gvsp_frame_payload(p.roi_h, gvsp_frame_chunks(s.chunk_mode != 0U));
    return gvsp_profile_payload((uint8_t)s.lines[c], comps_of(c), s.out_mode[c] != 0U, s.chunk_mode != 0U);
}

static uint16_t src_read(uint8_t c, uint32_t off, uint32_t *v)
{
    static const uint32_t k_comp_id[4] = { 1, 4, 5, 6 };   /* SFNC: Intensity, Range, Reflectance, Confidence */
    camera_params_t p;
    laser_cfg_t lc;
    laser_telemetry_t lt;
    mm_info_t mi;
    uint32_t rg = 0, i;

    if (off >= 0x010U && off < 0x030U) {        /* RegionSelector: Region0, Scan3dExtraction0 */
        rg = (off - 0x010U) >> 4;
        off = 0x010U + ((off - 0x010U) & 0xFU);
    }
    if (off >= 0x100U && off < 0x130U) {        /* ComponentSelector */
        i = (off & 0xFU) >> 2;
        switch (off & ~0xFU) {
        case 0x100: *v = s.comp_en[c][i]; return ST_SUCCESS;
        case 0x110:
            *v = (i == 1U) ? (s.out_mode[c] ? GEV_SRC_OFF_PIXEL_FORMAT_COORD3D_AC16 : GEV_SRC_OFF_PIXEL_FORMAT_COORD3D_C16)
               : (i == 3U) ? GEV_SRC_OFF_PIXEL_FORMAT_CONFIDENCE8 : GEV_SRC_OFF_PIXEL_FORMAT_MONO8;
            return ST_SUCCESS;
        default:    *v = k_comp_id[i]; return ST_SUCCESS;
        }
    }
    (void)camera_cached_params(c, &p);
    switch (off) {
    case GEV_SRC_OFF_DEVICE_SCAN_TYPE:   *v = s.scan_type[c]; return ST_SUCCESS;
    case GEV_SRC_OFF_SENSOR_WIDTH:       *v = VIDEO_FRAME_WIDTH; return ST_SUCCESS;
    case GEV_SRC_OFF_SENSOR_HEIGHT:      *v = VIDEO_FRAME_HEIGHT; return ST_SUCCESS;
    case GEV_SRC_OFF_WIDTH:              *v = VIDEO_FRAME_WIDTH; return ST_SUCCESS;   /* both regions */
    case GEV_SRC_OFF_HEIGHT:             *v = rg ? s.lines[c] : p.roi_h; return ST_SUCCESS;
    case GEV_SRC_OFF_OFFSET_X:           *v = 0; return ST_SUCCESS;
    case GEV_SRC_OFF_OFFSET_Y:           *v = rg ? 0U : p.offset_y; return ST_SUCCESS;
    case GEV_SRC_OFF_EXPOSURE_TIME:      *v = p.exp; return ST_SUCCESS;
    case GEV_SRC_OFF_GAIN:               *v = p.gain; return ST_SUCCESS;
    case GEV_SRC_OFF_ACQUISITION_FRAME_RATE: *v = p.fps; return ST_SUCCESS;
    case GEV_SRC_OFF_TRIGGER_MODE:       *v = p.trg_mode ? 1U : 0U; return ST_SUCCESS;
    case GEV_SRC_OFF_TEST_PATTERN:       *v = p.testpat & 1U; return ST_SUCCESS;
    case GEV_SRC_OFF_TRIGGER_DELAY:      *v = sync_get(w_delay(c)); return ST_SUCCESS;
    case GEV_SRC_OFF_TRIGGER_PULSE_WIDTH: *v = sync_get(w_width(c)); return ST_SUCCESS;
    case GEV_SRC_OFF_TRIGGER_OUTPUT_INVERTER: *v = (sync_get(SYNC_W_POLARITY) >> c) & 1U; return ST_SUCCESS;
    case GEV_SRC_OFF_ACQUISITION_FRAME_RATE_LIMIT: return max_fps(c, v);
    case GEV_SRC_OFF_LASER_FINDER_THRESHOLD: laser_cfg_get(c, &lc); *v = lc.thresh; return ST_SUCCESS;
    case GEV_SRC_OFF_LASER_FINDER_FLOOR:     laser_cfg_get(c, &lc); *v = lc.offset; return ST_SUCCESS;
    case GEV_SRC_OFF_LASER_FINDER_GAP:       laser_cfg_get(c, &lc); *v = lc.gap; return ST_SUCCESS;
    case GEV_SRC_OFF_LASER_FINDER_WINDOW_START: laser_cfg_get(c, &lc); *v = lc.win_lo; return ST_SUCCESS;
    case GEV_SRC_OFF_LASER_FINDER_WINDOW_END:   laser_cfg_get(c, &lc); *v = lc.win_hi; return ST_SUCCESS;
    case GEV_SRC_OFF_LASER_FINDER_MIN_SUM:   laser_cfg_get(c, &lc); *v = lc.min_sum; return ST_SUCCESS;
    case GEV_SRC_OFF_LASER_FINDER_WIDTH_MAX: laser_cfg_get(c, &lc); *v = lc.width_max; return ST_SUCCESS;
    case GEV_SRC_OFF_LASER_FINDER_STATUS:
        *v = laser_read_telemetry(c, &lt)
           ? (0x100U | (lt.loaded ? 1U : 0U) | (lt.enable ? 2U : 0U) | (s.lf_ack[c] ? 4U : 0U)) : 0U;
        return ST_SUCCESS;
    case GEV_SRC_OFF_SCAN3D_OUTPUT_MODE: *v = s.out_mode[c]; return ST_SUCCESS;
    case GEV_SRC_OFF_SCAN3D_COORDINATE_UNITS_LOG2:
    case GEV_SRC_OFF_CALIBRATION_TABLE_ID:
    case GEV_SRC_OFF_CALIBRATION_TABLE_CRC:
    case GEV_SRC_OFF_CALIBRATION_VALID:
    case GEV_SRC_OFF_CALIBRATION_BAND_STATUS:
    case GEV_SRC_OFF_CALIBRATION_BAND_CRC:
        mm_info(c, &mi);
        if (mi.state != MM_ST_READY) memset(&mi.hdr, 0, sizeof(mi.hdr));
        *v = (off == GEV_SRC_OFF_SCAN3D_COORDINATE_UNITS_LOG2) ? mi.hdr.unit_shift
           : (off == GEV_SRC_OFF_CALIBRATION_TABLE_ID) ? mi.hdr.id
           : (off == GEV_SRC_OFF_CALIBRATION_TABLE_CRC) ? mi.hdr.crc
           : (off == GEV_SRC_OFF_CALIBRATION_BAND_STATUS) ? mi.off_why
           : (off == GEV_SRC_OFF_CALIBRATION_BAND_CRC) ? mi.band_crc
           : (mi.state == MM_ST_READY && mi.off_why == MM_OFF_NONE && mi.echo.valid && mi.echo.band_valid) ? 1U : 0U;
        return ST_SUCCESS;
    case GEV_SRC_OFF_CALIBRATION_TIMESTAMP: return ST_NOT_YET;   /* not in the table header yet */
    case GEV_SRC_OFF_SCAN3D_DISTANCE_UNIT:
        *v = s.out_mode[c] ? GEV_SRC_OFF_SCAN3D_DISTANCE_UNIT_MILLIMETER : GEV_SRC_OFF_SCAN3D_DISTANCE_UNIT_PIXEL;
        return ST_SUCCESS;
    case GEV_SRC_OFF_SCAN3D_EXTRACTION_METHOD: *v = 0; return ST_SUCCESS;
    case GEV_SRC_OFF_SCAN3D_INVALID_DATA_FLAG: *v = 1; return ST_SUCCESS;
    case GEV_SRC_OFF_PAYLOAD_SIZE:       *v = payload_size(c); return ST_SUCCESS;
    case GEV_SRC_OFF_SOURCE_FRAME_COUNTER:
    case GEV_SRC_OFF_SOURCE_TRIGGERS_SEEN:
    case GEV_SRC_OFF_SOURCE_TRIGGERS_IGNORED:
    case GEV_SRC_OFF_SOURCE_PROFILE_BLOCKS:
    case GEV_SRC_OFF_SOURCE_PROFILE_NO_LINE_POINTS:
        if (!status_words()) return ST_ERROR;
        *v = (off == GEV_SRC_OFF_SOURCE_FRAME_COUNTER) ? s.st[c ? 38 : 1]
           : (off == GEV_SRC_OFF_SOURCE_TRIGGERS_SEEN) ? s.st[c ? 36 : 26]
           : (off == GEV_SRC_OFF_SOURCE_TRIGGERS_IGNORED) ? s.st[c ? 37 : 27]
           : (off == GEV_SRC_OFF_SOURCE_PROFILE_BLOCKS) ? (s.st[31U + c] >> 16) : (s.st[31U + c] & 0xFFFFU);
        return ST_SUCCESS;
    case GEV_SRC_OFF_STREAM_DELIVERY_MODE: *v = s.delivery[c]; return ST_SUCCESS;
    case GEV_SRC_OFF_STREAM_ACKED_BLOCK_ID: *v = s.acked[c][0]; return ST_SUCCESS;
    case GEV_SRC_OFF_STREAM_ACKED_BLOCK_ID + 4U: *v = s.acked[c][1]; return ST_SUCCESS;
    case GEV_SRC_OFF_STREAM_HEAD_BLOCK_ID: case GEV_SRC_OFF_STREAM_HEAD_BLOCK_ID + 4U:
    case GEV_SRC_OFF_STREAM_TAIL_BLOCK_ID: case GEV_SRC_OFF_STREAM_TAIL_BLOCK_ID + 4U:
    case GEV_SRC_OFF_STREAM_RING_FREE: case GEV_SRC_OFF_STREAM_OVERFLOW_COUNT:
    case GEV_SRC_OFF_STREAM_RESEND_COUNT: {
        gvsp_delivery_t d;
        gvsp_delivery_status(c, &d);
        *v = (off == GEV_SRC_OFF_STREAM_HEAD_BLOCK_ID) ? (uint32_t)(d.head >> 32)
           : (off == GEV_SRC_OFF_STREAM_HEAD_BLOCK_ID + 4U) ? (uint32_t)d.head
           : (off == GEV_SRC_OFF_STREAM_TAIL_BLOCK_ID) ? (uint32_t)(d.tail >> 32)
           : (off == GEV_SRC_OFF_STREAM_TAIL_BLOCK_ID + 4U) ? (uint32_t)d.tail
           : (off == GEV_SRC_OFF_STREAM_RING_FREE) ? d.ring_free
           : (off == GEV_SRC_OFF_STREAM_OVERFLOW_COUNT) ? d.overflow : d.resends;
        return ST_SUCCESS;
    }
    default: return ST_INVALID_ADDRESS;
    }
}

static uint16_t src_write(const req_t *r, uint8_t c, uint32_t off, uint32_t v)
{
    camera_params_t p;
    uint32_t rg = 0, dummy;

    if (off >= 0x010U && off < 0x030U) {
        rg = (off - 0x010U) >> 4;
        off = 0x010U + ((off - 0x010U) & 0xFU);
    }
    if (off >= 0x100U && off < 0x110U) {        /* ComponentEnable */
        if (v > 1U) return ST_INVALID_PARAM;
        s.comp_en[c][(off & 0xFU) >> 2] = v;
        return ST_SUCCESS;
    }
    (void)camera_cached_params(c, &p);
    switch (off) {
    case GEV_SRC_OFF_DEVICE_SCAN_TYPE:
        if (v > 1U) return ST_INVALID_PARAM;
        s.scan_type[c] = v;
        return ST_SUCCESS;
    case GEV_SRC_OFF_HEIGHT:
        if (rg == 0U) return height_set(r, v);
        if (v < 1U || v > 16U || (v & (v - 1U))) return ST_INVALID_PARAM;   /* a power of two: block id -> slots */
        s.lines[c] = v;
        return ST_SUCCESS;
    case GEV_SRC_OFF_OFFSET_Y:
        if (rg != 0U) return (v == 0U) ? ST_SUCCESS : ST_INVALID_PARAM;
        if ((v & 3U) || v + p.roi_h > VIDEO_FRAME_HEIGHT) return ST_INVALID_PARAM;
        p.offset_y = v;
        return cam_cfg(r, c, &p);
    case GEV_SRC_OFF_EXPOSURE_TIME:      return exposure_set(c, v, -1);
    case GEV_SRC_OFF_GAIN:               return (v > 0xFFFFU) ? ST_INVALID_PARAM : exposure_set(c, p.exp, (int32_t)v);
    case GEV_SRC_OFF_ACQUISITION_FRAME_RATE:
        if (v == 0U) return ST_INVALID_PARAM;
        p.fps = v;
        return cam_cfg(r, c, &p);
    case GEV_SRC_OFF_TRIGGER_MODE:
    case GEV_SRC_OFF_TEST_PATTERN:
        if (v > 1U) return ST_INVALID_PARAM;
        if (off == GEV_SRC_OFF_TRIGGER_MODE) p.trg_mode = (uint8_t)v;
        else p.testpat = (uint8_t)v;
        return cam_cfg(r, c, &p);
    case GEV_SRC_OFF_TRIGGER_DELAY:      return sync_channel(c, 0, v, sync_get(w_width(c)));
    case GEV_SRC_OFF_TRIGGER_PULSE_WIDTH: return sync_channel(c, 0, sync_get(w_delay(c)), v);
    case GEV_SRC_OFF_TRIGGER_OUTPUT_INVERTER:
        return (v > 1U) ? ST_INVALID_PARAM : sync_pol_set(1U << c, v);
    case GEV_SRC_OFF_LASER_FINDER_THRESHOLD: case GEV_SRC_OFF_LASER_FINDER_FLOOR:
    case GEV_SRC_OFF_LASER_FINDER_GAP: case GEV_SRC_OFF_LASER_FINDER_WINDOW_START:
    case GEV_SRC_OFF_LASER_FINDER_WINDOW_END: case GEV_SRC_OFF_LASER_FINDER_MIN_SUM:
    case GEV_SRC_OFF_LASER_FINDER_WIDTH_MAX:
        return finder_set(c, off, v);
    case GEV_SRC_OFF_SCAN3D_OUTPUT_MODE:
        if (v > 1U) return ST_INVALID_PARAM;
        s.out_mode[c] = v;
        return ST_SUCCESS;
    case GEV_SRC_OFF_STREAM_DELIVERY_MODE:
        if (v > 1U) return ST_INVALID_PARAM;
        s.delivery[c] = v;
        gvsp_delivery_set(c, v == GEV_SRC_OFF_STREAM_DELIVERY_MODE_GUARANTEED);
        return ST_SUCCESS;
    // 64-bit, high word first: the low word's write is the ack.
    case GEV_SRC_OFF_STREAM_ACKED_BLOCK_ID: s.acked[c][0] = v; return ST_SUCCESS;
    case GEV_SRC_OFF_STREAM_ACKED_BLOCK_ID + 4U:
        s.acked[c][1] = v;
        gvsp_ack(c, ((uint64_t)s.acked[c][0] << 32) | v);
        return ST_SUCCESS;
    default:
        return (src_read(c, off + rg * 0x10U, &dummy) == ST_INVALID_ADDRESS) ? ST_INVALID_ADDRESS : ST_WRITE_PROTECT;
    }
}

// ---- manufacturer registers: file access (0x0130..0x0134, 0x0168 / 0x016A paths) ----

static uint32_t file_size(uint32_t sel)
{
    if (sel <= GEV_REG_FILE_SELECTOR_MMTABLE1) return MM_HDR_BYTES + MM_TABLE_BYTES;
    if (sel == GEV_REG_FILE_SELECTOR_CALIBRATION) return LASER_CALIB_BYTES;
    if (sel == GEV_REG_FILE_SELECTOR_SETTINGSIMAGE) {
        uint8_t b[2] = { FILE_SETTINGS_SEC, 0 };     /* RAM settings */
        int n = vmsp_call(0x0168, b, sizeof(b), s_vout, sizeof(s_vout));
        return (n >= 8 && s_vout[0] == 0) ? rd16(s_vout + 4) : 0U;
    }
    return 0;
}

// Write f.len bytes of the buffer at f.off. *res = bytes, or the VMSP status on failure.
static bool file_write(uint32_t *res)
{
    const uint8_t *d = f.buf;
    uint32_t off = f.off, n = f.len, k;

    if (f.open_sel <= GEV_REG_FILE_SELECTOR_MMTABLE1) {
        while (n > 0U) {
            if (off < MM_HDR_BYTES) {               /* the 20 B commit header first */
                k = (n < MM_HDR_BYTES - off) ? n : MM_HDR_BYTES - off;
                memcpy(f.hdr + off, d, k);
            } else {                                /* table bytes: 0x0132, in order */
                k = n;
                s_vbody[0] = (uint8_t)f.open_sel;
                s_vbody[1] = s_vbody[2] = s_vbody[3] = 0;
                wr32(s_vbody + 4, off - MM_HDR_BYTES);
                memcpy(s_vbody + 8, d, k);
                if (vcall(0x0132, s_vbody, 8U + k) != ST_SUCCESS) { *res = s_vout[0]; return false; }
            }
            off += k; d += k; n -= k;
        }
    } else {
        uint32_t cap = (f.open_sel == GEV_REG_FILE_SELECTOR_CALIBRATION) ? LASER_CALIB_BYTES : sizeof(f.img);
        if (off > cap || n > cap - off) { *res = 0; return false; }
        memcpy(f.img + off, d, n);
        if (off + n > f.img_len) f.img_len = off + n;
    }
    *res = f.len;
    return true;
}

static bool file_read(uint32_t *res)
{
    const uint8_t *src;
    uint32_t n;

    if (f.open_sel == GEV_REG_FILE_SELECTOR_CALIBRATION) {
        n = laser_calib_get(f.img, LASER_CALIB_BYTES);
        src = f.img;
    } else {
        uint8_t b[2] = { FILE_SETTINGS_SEC, 0 };
        int r = vmsp_call(0x0168, b, sizeof(b), s_vout, sizeof(s_vout));
        if (r < 8 || s_vout[0] != 0) { *res = (r < 1) ? 0U : s_vout[0]; return false; }
        n = rd16(s_vout + 4);
        src = s_vout + 8;
    }
    if (f.off >= n) { *res = 0; return true; }
    n = (n - f.off < f.len) ? n - f.off : f.len;
    memcpy(f.buf, src + f.off, n);
    *res = n;
    return true;
}

// Close of a written file: the commit opcode.
static bool file_commit(const req_t *r, uint32_t *res)
{
    uint16_t st;

    if (f.open_sel <= GEV_REG_FILE_SELECTOR_MMTABLE1) {
        if (f.hdr[0] != f.open_sel) { *res = 0x09; return false; }   /* header for the other camera */
        f.hdr[18] = (uint8_t)((f.hdr[18] & ~1U) | (f.save ? 1U : 0U));
        pending(r);
        st = vcall(0x0134, f.hdr, MM_HDR_BYTES);
        if (st == ST_SUCCESS && f.save && s_vout[16] != 1U) { *res = 0x100U | s_vout[18]; return false; }
    } else if (f.open_sel == GEV_REG_FILE_SELECTOR_CALIBRATION) {
        st = vcall(0x0130, f.img, f.img_len);
    } else {
        s_vbody[0] = FILE_SETTINGS_SEC;
        s_vbody[1] = f.save ? 1U : 0U;
        s_vbody[2] = s_vbody[3] = 0;
        memcpy(s_vbody + 4, f.img, f.img_len);
        if (f.save) pending(r);
        st = vcall(0x016A, s_vbody, 4U + f.img_len);
    }
    *res = (st == ST_SUCCESS) ? 0U : s_vout[0];
    return st == ST_SUCCESS;
}

static void file_exec(const req_t *r)
{
    uint32_t res = 0;
    bool ok = false;

    switch (f.op) {
    case GEV_REG_FILE_OPERATION_SELECTOR_OPEN:
        // shortcut: no read-back of an mm table yet (0x0136 reports its id and CRC).
        if (!f.open && f.sel <= GEV_REG_FILE_SELECTOR_SETTINGSIMAGE && f.mode <= 1U &&
            !(f.mode == GEV_REG_FILE_OPEN_MODE_READ && f.sel <= GEV_REG_FILE_SELECTOR_MMTABLE1)) {
            f.open = true;
            f.open_sel = f.sel;
            f.open_mode = f.mode;
            f.img_len = 0;
            memset(f.hdr, 0, sizeof(f.hdr));
            ok = true;
        }
        break;
    case GEV_REG_FILE_OPERATION_SELECTOR_CLOSE:
        if (f.open) {
            ok = (f.open_mode == GEV_REG_FILE_OPEN_MODE_WRITE) ? file_commit(r, &res) : true;
            f.open = false;
        }
        break;
    case GEV_REG_FILE_OPERATION_SELECTOR_READ:
        if (f.open && f.open_mode == GEV_REG_FILE_OPEN_MODE_READ && f.len <= FILE_BUF_BYTES) ok = file_read(&res);
        break;
    case GEV_REG_FILE_OPERATION_SELECTOR_WRITE:
        if (f.open && f.open_mode == GEV_REG_FILE_OPEN_MODE_WRITE && f.len <= FILE_BUF_BYTES) ok = file_write(&res);
        break;
    default:
        break;
    }
    f.status = ok ? GEV_REG_FILE_OPERATION_STATUS_SUCCESS : GEV_REG_FILE_OPERATION_STATUS_FAILURE;
    f.result = res;
}

// ---- manufacturer registers --------------------------------------------------------

static bool fbuf_range(uint32_t a, uint32_t n)
{
    return a >= GEV_REG_FILE_ACCESS_BUFFER && a - GEV_REG_FILE_ACCESS_BUFFER <= FILE_BUF_BYTES &&
           n <= FILE_BUF_BYTES - (a - GEV_REG_FILE_ACCESS_BUFFER);
}

static uint16_t mfr_read(uint32_t a, uint32_t *v)
{
    uint32_t recent, total, drain, speed;

    if (a >= GEV_SRC_BASE && a < GEV_SRC_BASE + GEV_SRC_STRIDE * VIDEO_CAM_COUNT)
        return src_read((uint8_t)((a - GEV_SRC_BASE) / GEV_SRC_STRIDE), (a - GEV_SRC_BASE) % GEV_SRC_STRIDE, v);
    if (fbuf_range(a, 4)) { *v = rd32(f.buf + (a - GEV_REG_FILE_ACCESS_BUFFER)); return ST_SUCCESS; }
    if (a >= GEV_REG_DEVICE_FIRMWARE_VERSION && a < GEV_REG_DEVICE_FIRMWARE_VERSION + 32U) {
        *v = str_word(s.fw_ver, 32, a - GEV_REG_DEVICE_FIRMWARE_VERSION);
        return ST_SUCCESS;
    }
    if (a >= GEV_REG_CHUNK_ENABLE && a < GEV_REG_CHUNK_ENABLE + 16U) { *v = s.chunk_en[(a - GEV_REG_CHUNK_ENABLE) >> 2]; return ST_SUCCESS; }
    if (a >= GEV_REG_EVENT_NOTIFICATION && a < GEV_REG_EVENT_NOTIFICATION + 16U) { *v = s.event_en[(a - GEV_REG_EVENT_NOTIFICATION) >> 2]; return ST_SUCCESS; }
    switch (a) {
    case GEV_REG_TL_PARAMS_LOCKED:        *v = s.tl_locked; return ST_SUCCESS;
    case GEV_REG_DEVICE_FPGA_VERSION:                               /* 0: a bitstream without the id */
        if (s.fpga_id == 0U) return ST_NOT_YET;
        *v = s.fpga_id;
        return ST_SUCCESS;
    case GEV_REG_DEVICE_FIRMWARE_CRC:     *v = s.fw_crc; return ST_SUCCESS;
    case GEV_REG_DEVICE_UPTIME_SECONDS:   *v = xTaskGetTickCount() / configTICK_RATE_HZ; return ST_SUCCESS;
    case GEV_REG_DEVICE_STORED_DATA_ALARM: *v = spi_flash_alarm_get(); return ST_SUCCESS;
    case GEV_REG_DEVICE_MAC_ADDRESS_SET_HIGH: mac_set_load(); *v = rd16(s.mac_set); return ST_SUCCESS;
    case GEV_REG_DEVICE_MAC_ADDRESS_SET_LOW:  mac_set_load(); *v = rd32(s.mac_set + 2); return ST_SUCCESS;
    case GEV_REG_CHUNK_MODE_ACTIVE:       *v = s.chunk_mode; return ST_SUCCESS;
    case GEV_REG_ACQUISITION_MODE:        *v = s.acq_mode; return ST_SUCCESS;
    case GEV_REG_ACQUISITION_FRAME_COUNT: *v = s.acq_count; return ST_SUCCESS;
    case GEV_REG_TRIGGER_SOURCE:
        *v = (sync_get(SYNC_W_CTRL) & SYNC_CTRL_SRC_MASK) >> SYNC_CTRL_SRC_SHIFT;   /* VMSP 0 CORE, 1 TIMER, 2 EXT */
        return ST_SUCCESS;
    case GEV_REG_TRIGGER_ACTIVATION:      *v = (sync_get(SYNC_W_CTRL) & SYNC_CTRL_EXT_FALL) ? 1U : 0U; return ST_SUCCESS;
    case GEV_REG_LINE_DEBOUNCER_TIME:     *v = sync_get(SYNC_W_EXT_FILTER); return ST_SUCCESS;
    case GEV_REG_LINE_MODE:               *v = GEV_REG_LINE_MODE_INPUT; return ST_SUCCESS;
    case GEV_REG_LASER_ENABLE:            *v = (sync_get(SYNC_W_CTRL) & SYNC_CTRL_LASER_EN) ? 1U : 0U; return ST_SUCCESS;
    case GEV_REG_LASER_MODE:              *v = sync_get(SYNC_W_LASER_MODE); return ST_SUCCESS;
    case GEV_REG_LASER_PULSE_DELAY:       *v = sync_get(SYNC_W_LASER_DELAY); return ST_SUCCESS;
    case GEV_REG_LASER_PULSE_WIDTH:       *v = sync_get(SYNC_W_LASER_WIDTH); return ST_SUCCESS;
    case GEV_REG_LASER_INVERTER:          *v = (sync_get(SYNC_W_POLARITY) >> 2) & 1U; return ST_SUCCESS;
    case GEV_REG_TRIGGER_GENERATOR_FREQUENCY:   gen_load(); *v = s.gen_rate; return ST_SUCCESS;
    case GEV_REG_TRIGGER_GENERATOR_PULSE_COUNT: gen_load(); *v = s.gen_count; return ST_SUCCESS;
    case GEV_REG_TRIGGER_GENERATOR_PULSE_WIDTH: gen_load(); *v = s.gen_width; return ST_SUCCESS;
    case GEV_REG_TRIGGER_GENERATOR_INVERTER:    gen_load(); *v = s.gen_inv; return ST_SUCCESS;
    case GEV_REG_SYNC_STATE: case GEV_REG_SYNC_TRIGGERS_ACCEPTED: case GEV_REG_SYNC_TRIGGER_OVERLOADS:
    case GEV_REG_SYNC_EXTERNAL_EDGES: case GEV_REG_TRIGGER_GENERATOR_PULSES_SENT: case GEV_REG_SOFTWARE_TRIGGER_COUNT:
        if (!status_words()) return ST_ERROR;
        *v = (a == GEV_REG_SYNC_STATE) ? s.st[5] : (a == GEV_REG_SYNC_TRIGGERS_ACCEPTED) ? s.st[6]
           : (a == GEV_REG_SYNC_TRIGGER_OVERLOADS) ? s.st[7] : (a == GEV_REG_SYNC_EXTERNAL_EDGES) ? s.st[8]
           : (a == GEV_REG_TRIGGER_GENERATOR_PULSES_SENT) ? s.st[4] : s.st[12];
        return ST_SUCCESS;
    case GEV_REG_USER_SET_SELECTOR:       *v = s.user_set; return ST_SUCCESS;
    case GEV_REG_USER_SET_DEFAULT:        *v = GEV_REG_USER_SET_DEFAULT_USERSET1; return ST_SUCCESS;  /* the store loads at boot */
    case GEV_REG_USER_SET_STORE_STATUS:   *v = settings_status_word(); return ST_SUCCESS;
    case GEV_REG_FILE_SELECTOR:           *v = f.sel; return ST_SUCCESS;
    case GEV_REG_FILE_OPERATION_SELECTOR: *v = f.op; return ST_SUCCESS;
    case GEV_REG_FILE_OPEN_MODE:          *v = f.mode; return ST_SUCCESS;
    case GEV_REG_FILE_ACCESS_OFFSET:      *v = f.off; return ST_SUCCESS;
    case GEV_REG_FILE_ACCESS_LENGTH:      *v = f.len; return ST_SUCCESS;
    case GEV_REG_FILE_OPERATION_STATUS:   *v = f.status; return ST_SUCCESS;
    case GEV_REG_FILE_OPERATION_RESULT:   *v = f.result; return ST_SUCCESS;
    case GEV_REG_FILE_SIZE:               *v = file_size(f.sel); return ST_SUCCESS;
    case GEV_REG_FILE_SAVE_TO_FLASH:      *v = f.save; return ST_SUCCESS;
    case GEV_REG_ETH_RX_WATCHDOG_LOST_RECENT: case GEV_REG_ETH_RX_WATCHDOG_LOST_TOTAL:
    case GEV_REG_ETH_RX_WATCHDOG_DRAINED: case GEV_REG_ETH_MAC_SPEED_CORRECTIONS: case GEV_REG_DEVICE_STATUS_BITS:
        eth_rx_health(&recent, &total, &drain, &speed);
        *v = (a == GEV_REG_ETH_RX_WATCHDOG_LOST_RECENT) ? recent : (a == GEV_REG_ETH_RX_WATCHDOG_LOST_TOTAL) ? total
           : (a == GEV_REG_ETH_RX_WATCHDOG_DRAINED) ? drain : (a == GEV_REG_ETH_MAC_SPEED_CORRECTIONS) ? speed
           : (video_status_bits() | ((recent > 0U) ? 1U : 0U));
        return ST_SUCCESS;
    // write-only commands
    case GEV_REG_DEVICE_RESET: case GEV_REG_ACQUISITION_START: case GEV_REG_ACQUISITION_STOP:
    case GEV_REG_DEVICE_MAC_ADDRESS_STORE: case GEV_REG_DEVICE_MAC_ADDRESS_ERASE:
    case GEV_REG_TRIGGER_SOFTWARE: case GEV_REG_TRIGGER_GENERATOR_START: case GEV_REG_TRIGGER_GENERATOR_STOP:
    case GEV_REG_USER_SET_LOAD: case GEV_REG_USER_SET_SAVE: case GEV_REG_FILE_OPERATION_EXECUTE:
    default:
        return ST_INVALID_ADDRESS;
    }
}

static uint16_t mfr_write(const req_t *r, uint32_t a, uint32_t v)
{
    uint32_t dummy;
    uint16_t st;

    if (a >= GEV_SRC_BASE && a < GEV_SRC_BASE + GEV_SRC_STRIDE * VIDEO_CAM_COUNT)
        return src_write(r, (uint8_t)((a - GEV_SRC_BASE) / GEV_SRC_STRIDE), (a - GEV_SRC_BASE) % GEV_SRC_STRIDE, v);
    if (fbuf_range(a, 4)) { wr32(f.buf + (a - GEV_REG_FILE_ACCESS_BUFFER), v); return ST_SUCCESS; }
    if (a >= GEV_REG_CHUNK_ENABLE && a < GEV_REG_CHUNK_ENABLE + 16U) {
        if (v > 1U) return ST_INVALID_PARAM;
        s.chunk_en[(a - GEV_REG_CHUNK_ENABLE) >> 2] = v;
        return ST_SUCCESS;
    }
    if (a >= GEV_REG_EVENT_NOTIFICATION && a < GEV_REG_EVENT_NOTIFICATION + 16U) {
        if (v > 1U) return ST_INVALID_PARAM;
        s.event_en[(a - GEV_REG_EVENT_NOTIFICATION) >> 2] = v;
        return ST_SUCCESS;
    }
    switch (a) {
    case GEV_REG_DEVICE_RESET:
        if (v != 0U) s.reset_req = true;                 /* after the ack (R-537cd), handle() */
        return ST_SUCCESS;
    case GEV_REG_TL_PARAMS_LOCKED:   if (v > 1U) return ST_INVALID_PARAM; s.tl_locked = v; return ST_SUCCESS;
    // MAC address (VMSP 0x0005): set in two halves, stored by a command, applied at the next boot.
    case GEV_REG_DEVICE_MAC_ADDRESS_SET_HIGH:
        if (v > 0xFFFFU) return ST_INVALID_PARAM;
        mac_set_load();
        wr16(s.mac_set, (uint16_t)v);
        return ST_SUCCESS;
    case GEV_REG_DEVICE_MAC_ADDRESS_SET_LOW:
        mac_set_load();
        wr32(s.mac_set + 2, v);
        return ST_SUCCESS;
    case GEV_REG_DEVICE_MAC_ADDRESS_STORE:
        if (v == 0U) return ST_SUCCESS;
        mac_set_load();
        if (!net_mac_valid(s.mac_set)) return ST_INVALID_PARAM;
        pending(r);
        return (net_mac_store(s.mac_set) == 0) ? ST_SUCCESS : ST_ERROR;
    case GEV_REG_DEVICE_MAC_ADDRESS_ERASE:
        if (v == 0U) return ST_SUCCESS;
        s.mac_dirty = false;
        pending(r);
        return (net_mac_store(NULL) == 0) ? ST_SUCCESS : ST_ERROR;
    case GEV_REG_CHUNK_MODE_ACTIVE:  if (v > 1U) return ST_INVALID_PARAM; s.chunk_mode = v; return ST_SUCCESS;
    case GEV_REG_ACQUISITION_MODE:   if (v > 2U) return ST_INVALID_PARAM; s.acq_mode = v; return ST_SUCCESS;
    case GEV_REG_ACQUISITION_FRAME_COUNT: if (v < 1U) return ST_INVALID_PARAM; s.acq_count = v; return ST_SUCCESS;
    case GEV_REG_ACQUISITION_START:  return acquisition(r, true);
    case GEV_REG_ACQUISITION_STOP:   return acquisition(r, false);
    case GEV_REG_TRIGGER_SOURCE:
        if (v > 2U) return ST_INVALID_PARAM;
        return sync_ctrl_set(SYNC_CTRL_SRC_MASK, v << SYNC_CTRL_SRC_SHIFT);
    case GEV_REG_TRIGGER_ACTIVATION:
        if (v > 1U) return ST_INVALID_PARAM;
        return sync_ctrl_set(SYNC_CTRL_EXT_FALL, v ? SYNC_CTRL_EXT_FALL : 0U);
    case GEV_REG_TRIGGER_SOFTWARE:   return vcall(0x0145, NULL, 0);
    case GEV_REG_LINE_DEBOUNCER_TIME:
        return sync_control(sync_get(SYNC_W_CTRL), v, sync_get(SYNC_W_POLARITY));
    case GEV_REG_LASER_ENABLE:
        if (v > 1U) return ST_INVALID_PARAM;
        return sync_ctrl_set(SYNC_CTRL_LASER_EN, v ? SYNC_CTRL_LASER_EN : 0U);
    case GEV_REG_LASER_MODE:
        return sync_channel(2, v, sync_get(SYNC_W_LASER_DELAY), sync_get(SYNC_W_LASER_WIDTH));
    case GEV_REG_LASER_PULSE_DELAY:
        return sync_channel(2, sync_get(SYNC_W_LASER_MODE), v, sync_get(SYNC_W_LASER_WIDTH));
    case GEV_REG_LASER_PULSE_WIDTH:
        return sync_channel(2, sync_get(SYNC_W_LASER_MODE), sync_get(SYNC_W_LASER_DELAY), v);
    case GEV_REG_LASER_INVERTER:
        return (v > 1U) ? ST_INVALID_PARAM : sync_pol_set(4U, v);
    case GEV_REG_TRIGGER_GENERATOR_FREQUENCY:
    case GEV_REG_TRIGGER_GENERATOR_PULSE_COUNT:
    case GEV_REG_TRIGGER_GENERATOR_PULSE_WIDTH:
    case GEV_REG_TRIGGER_GENERATOR_INVERTER:
        // Kept until TriggerGeneratorStart; a running series takes the change at once (and
        // 0x0302 refuses a rate the cameras cannot follow).
        gen_load();
        if ((a == GEV_REG_TRIGGER_GENERATOR_PULSE_COUNT && v > 0xFFFFU) ||
            (a == GEV_REG_TRIGGER_GENERATOR_INVERTER && v > 1U)) return ST_INVALID_PARAM;
        {
            uint32_t *dst = (a == GEV_REG_TRIGGER_GENERATOR_FREQUENCY) ? &s.gen_rate
                          : (a == GEV_REG_TRIGGER_GENERATOR_PULSE_COUNT) ? &s.gen_count
                          : (a == GEV_REG_TRIGGER_GENERATOR_PULSE_WIDTH) ? &s.gen_width : &s.gen_inv;
            uint32_t old = *dst;
            *dst = v;
            if (!cam_trig_running()) return ST_SUCCESS;
            if ((st = gen_apply(false)) != ST_SUCCESS) *dst = old;
            return st;
        }
    case GEV_REG_TRIGGER_GENERATOR_START: gen_load(); return gen_apply(false);
    case GEV_REG_TRIGGER_GENERATOR_STOP:  gen_load(); return gen_apply(true);
    case GEV_REG_USER_SET_SELECTOR:
        if (v > 2U) return ST_INVALID_PARAM;
        s.user_set = v;
        return ST_SUCCESS;
    case GEV_REG_USER_SET_LOAD:
        if (s.user_set == GEV_REG_USER_SET_SELECTOR_DEFAULT) {
            uint8_t b[4];
            wr32(b, SETTINGS_RESET_GUARD);           /* defaults into RAM (0x0166) */
            return vcall(0x0166, b, sizeof(b));
        }
        if (s.user_set == GEV_REG_USER_SET_SELECTOR_USERSET1) {
            uint8_t b = SETTINGS_SEC_CFG;
            pending(r);
            return vcall(0x0162, &b, 1);
        }
        return ST_INVALID_PARAM;                     /* UserSet2: one set in the store */
    case GEV_REG_USER_SET_SAVE:
        if (s.user_set == GEV_REG_USER_SET_SELECTOR_USERSET1) {
            uint8_t b = SETTINGS_SEC_CFG;
            pending(r);
            return vcall(0x0160, &b, 1);
        }
        return ST_INVALID_PARAM;                     /* Default is read-only, UserSet2 absent */
    case GEV_REG_USER_SET_DEFAULT:
        return (v == GEV_REG_USER_SET_DEFAULT_USERSET1) ? ST_SUCCESS : ST_INVALID_PARAM;
    case GEV_REG_FILE_SELECTOR:      if (v > 3U) return ST_INVALID_PARAM; f.sel = v; return ST_SUCCESS;
    case GEV_REG_FILE_OPERATION_SELECTOR: if (v > 3U) return ST_INVALID_PARAM; f.op = v; return ST_SUCCESS;
    case GEV_REG_FILE_OPEN_MODE:     if (v > 1U) return ST_INVALID_PARAM; f.mode = v; return ST_SUCCESS;
    case GEV_REG_FILE_OPERATION_EXECUTE: file_exec(r); return ST_SUCCESS;
    case GEV_REG_FILE_ACCESS_OFFSET: f.off = v; return ST_SUCCESS;
    case GEV_REG_FILE_ACCESS_LENGTH: if (v > FILE_BUF_BYTES) return ST_INVALID_PARAM; f.len = v; return ST_SUCCESS;
    case GEV_REG_FILE_SAVE_TO_FLASH: if (v > 1U) return ST_INVALID_PARAM; f.save = v; return ST_SUCCESS;
    default:
        return (mfr_read(a, &dummy) == ST_INVALID_ADDRESS) ? ST_INVALID_ADDRESS : ST_WRITE_PROTECT;
    }
}

static uint16_t reg_read(uint32_t a, uint32_t *v)
{
    return (a >= 0xA000U) ? mfr_read(a, v) : boot_read(a, v);
}

static uint16_t reg_write(const req_t *r, uint32_t a, uint32_t v)
{
    return (a >= 0xA000U) ? mfr_write(r, a, v) : boot_write(r, a, v);
}

// ---- commands (GEV ch. 16) ------------------------------------------------------------

static uint16_t do_readreg(const uint8_t *p, uint16_t len, uint8_t *out, uint16_t *olen)
{
    uint16_t n = len / 4U, i, st = ST_SUCCESS;
    uint32_t a, v;

    if (len == 0U || (len & 3U) || n > REG_MAX) return ST_INVALID_HEADER;
    for (i = 0; i < n; ++i) {
        a = rd32(p + 4U * i);
        if (a & 3U) { st = ST_BAD_ALIGNMENT; break; }
        if ((st = reg_read(a, &v)) != ST_SUCCESS) break;
        wr32(out + 4U * i, v);
    }
    *olen = (uint16_t)(4U * i);                 /* the registers read before an error (R-165) */
    return st;
}

static uint16_t do_writereg(const req_t *r, const uint8_t *p, uint16_t len, uint8_t *out, uint16_t *olen)
{
    uint16_t n = len / 8U, i, st = ST_SUCCESS;
    uint32_t a;

    if (len == 0U || (len & 7U) || n > WREG_MAX) return ST_INVALID_HEADER;
    for (i = 0; i < n; ++i) {
        a = rd32(p + 8U * i);
        if (a & 3U) { st = ST_BAD_ALIGNMENT; break; }
        // Only the primary application writes; anyone may ask for control while it is free (R-172).
        if (!is_primary(r) && !(a == GEV_REG_GEV_CCP && s.ccp == 0U)) { st = ST_ACCESS_DENIED; break; }
        if ((st = reg_write(r, a, rd32(p + 8U * i + 4U))) != ST_SUCCESS) break;
    }
    if (st == ST_SUCCESS && (st = user_flush(r)) != ST_SUCCESS) i = (uint16_t)(n - 1U);
    s.user_dirty = false;
    wr16(out, 0);
    wr16(out + 2, i);                           /* writes done, or the failing index (R-169) */
    *olen = 4;
    return st;
}

static uint16_t mem_read(uint32_t a, uint8_t *dst, uint32_t n)
{
    uint32_t xend = gev_xml_addr + ((gev_xml_len + 3U) & ~3U), i, v;
    uint16_t st;

    if (a >= gev_xml_addr && a < xend) {        /* the zipped XML, padded to a word */
        if (n > xend - a) return ST_INVALID_ADDRESS;
        for (i = 0; i < n; ++i) {
            uint32_t k = a - gev_xml_addr + i;
            dst[i] = (k < gev_xml_len) ? gev_xml_zip[k] : 0U;
        }
        return ST_SUCCESS;
    }
    if (fbuf_range(a, n)) {
        memcpy(dst, f.buf + (a - GEV_REG_FILE_ACCESS_BUFFER), n);
        return ST_SUCCESS;
    }
    if (a > 0xFFFFFFFFU - n) return ST_INVALID_ADDRESS;
    for (i = 0; i < n; i += 4U) {
        if ((st = reg_read(a + i, &v)) != ST_SUCCESS) return st;
        wr32(dst + i, v);
    }
    return ST_SUCCESS;
}

static uint16_t do_readmem(const uint8_t *p, uint16_t len, uint8_t *out, uint16_t *olen)
{
    uint32_t a;
    uint16_t cnt, st;

    if (len < 8U) return ST_INVALID_HEADER;
    a = rd32(p);
    cnt = rd16(p + 6);
    if ((a & 3U) || (cnt & 3U)) return ST_BAD_ALIGNMENT;
    if (cnt == 0U || cnt > MEM_MAX) return ST_INVALID_PARAM;
    if ((st = mem_read(a, out + 4, cnt)) != ST_SUCCESS) return st;   /* all or nothing (R-184) */
    wr32(out, a);
    *olen = (uint16_t)(4U + cnt);
    return ST_SUCCESS;
}

static uint16_t do_writemem(const req_t *r, const uint8_t *p, uint16_t len, uint8_t *out, uint16_t *olen)
{
    uint32_t a, n, i = 0;
    uint16_t st = ST_SUCCESS;

    if (len < 4U) return ST_INVALID_HEADER;
    a = rd32(p);
    n = len - 4U;
    wr16(out, 0);
    *olen = 4;
    if ((a & 3U) || (n & 3U) || n == 0U) st = ST_BAD_ALIGNMENT;
    else if (n > MEM_MAX) st = ST_INVALID_PARAM;
    else if (!is_primary(r)) st = ST_ACCESS_DENIED;
    else if (fbuf_range(a, n)) { memcpy(f.buf + (a - GEV_REG_FILE_ACCESS_BUFFER), p + 4, n); i = n; }
    else if (a > 0xFFFFFFFFU - n) st = ST_INVALID_ADDRESS;
    else {
        for (i = 0; i < n; i += 4U)
            if ((st = reg_write(r, a + i, rd32(p + 4 + i))) != ST_SUCCESS) break;
        if (st == ST_SUCCESS && (st = user_flush(r)) != ST_SUCCESS) i = n - 4U;
    }
    s.user_dirty = false;
    wr16(out + 2, (uint16_t)i);                 /* bytes written, or the failing byte (R-194) */
    return st;
}

static void ack_header(uint8_t *a, uint16_t st, uint16_t cmd, uint16_t len, uint16_t req_id)
{
    wr16(a, st);
    wr16(a + 2, (uint16_t)(cmd + 1U));
    wr16(a + 4, len);
    wr16(a + 6, req_id);
}

// DISCOVERY_ACK: bootstrap 0x0000..0x00F7 (GEV fig. 16-2), in any VMSP mode and under
// exclusive access too (R-063); unicast on the board's subnet (R-142), broadcast to a PC
// outside it when the command allows (O-143).
static void do_discovery(const req_t *r, uint8_t flag)
{
    uint8_t a[8U + DISCOVERY_BYTES];
    struct sockaddr_in dst = r->src;
    uint32_t i, v;

    if (!r->ack) return;
    ack_header(a, ST_SUCCESS, CMD_DISCOVERY, DISCOVERY_BYTES, r->req_id);
    for (i = 0; i < DISCOVERY_BYTES; i += 4U) {
        v = 0;
        (void)boot_read(i, &v);                 /* reserved words read as 0 */
        wr32(a + 8U + i, v);
    }
    if ((flag & GVCP_F_BCAST) && !net_config_on_link(r->ip)) dst.sin_addr.s_addr = htonl(INADDR_BROADCAST);
    send_to(&dst, a, sizeof(a));
}

// FORCEIP (GEV 16.2): only for our MAC and only while nobody holds control (R-149, R-150).
// The address is not stored - the persistent one stays in the flash store.
static void do_forceip(const req_t *r, uint8_t flag, const uint8_t *p, uint16_t len)
{
    struct sockaddr_in dst = r->src;
    net_config_t c;
    uint16_t st = ST_SUCCESS;
    uint8_t a[8];

    if (len < 56U || memcmp(p + 2, gnetif.hwaddr, 6) != 0 || s.ccp != 0U) return;
    memcpy(c.ip, p + 20, 4);
    memcpy(c.mask, p + 36, 4);
    memcpy(c.gw, p + 52, 4);
    if (rd32(p + 20) == 0U) {                   /* restart the IP configuration, no ack (R-151) */
        close_channels();
        printf("[GVCP] FORCEIP 0: IP configuration restarts\r\n");
        net_config_restart();
        return;
    }
    if (!net_config_valid(&c)) {
        st = ST_INVALID_PARAM;
    } else {
        (void)net_config_set(&c, false);        /* the ack leaves from the new address (R-152) */
        printf("[GVCP] FORCEIP %u.%u.%u.%u/%u.%u.%u.%u gw %u.%u.%u.%u (not stored)\r\n", c.ip[0], c.ip[1], c.ip[2],
               c.ip[3], c.mask[0], c.mask[1], c.mask[2], c.mask[3], c.gw[0], c.gw[1], c.gw[2], c.gw[3]);
    }
    if (!r->ack) return;
    ack_header(a, st, CMD_FORCEIP, 0, r->req_id);
    if ((flag & GVCP_F_BCAST) || !net_config_on_link(r->ip)) dst.sin_addr.s_addr = htonl(INADDR_BROADCAST);
    send_to(&dst, a, sizeof(a));
}

static void handle(const uint8_t *rx, int n, const struct sockaddr_in *src)
{
    static uint8_t a[ACK_MAX];
    const uint8_t *p = rx + 8;
    uint16_t cmd, len, olen = 0, st;
    uint8_t flag;
    req_t r;

    if (n < 8 || rx[0] != GVCP_KEY) return;     /* not GVCP: silently (R-131) */
    flag = rx[1];
    cmd = rd16(rx + 2);
    len = rd16(rx + 4);
    r.src = *src;
    r.ip = ntohl(src->sin_addr.s_addr);
    r.port = ntohs(src->sin_port);
    r.req_id = rd16(rx + 6);
    r.ack = (flag & GVCP_F_ACK) != 0U;
    if (len > (uint16_t)(n - 8)) len = 0xFFFFU; /* claims more than arrived: invalid header below */

    if (lcd_hud_is_active()) {
        static uint32_t s_gvcp_rd = 0;
        if (cmd == CMD_READREG && (++s_gvcp_rd & 0x07U) != 1U) {
            lcd_hud_pulse_rx();
        } else {
            char gmsg[44];
            const char *cname = (cmd == CMD_DISCOVERY) ? "DISCOVERY" :
                                (cmd == CMD_FORCEIP)   ? "FORCEIP" :
                                (cmd == CMD_READREG)   ? "READREG" :
                                (cmd == CMD_WRITEREG)  ? "WRITEREG" :
                                (cmd == CMD_READMEM)   ? "READMEM" :
                                (cmd == CMD_WRITEMEM)  ? "WRITEMEM" : "CMD";
            snprintf(gmsg, sizeof(gmsg), "%s %u.%u.%u.%u", cname,
                     (unsigned)((r.ip >> 24) & 0xFFU), (unsigned)((r.ip >> 16) & 0xFFU),
                     (unsigned)((r.ip >> 8) & 0xFFU), (unsigned)(r.ip & 0xFFU));
            lcd_hud_log_exchange(LCD_COL_BLUE, "GVCP", gmsg);
        }
    }

    if (cmd == CMD_DISCOVERY) { if (len != 0xFFFFU) do_discovery(&r, flag); return; }
    if (cmd == CMD_FORCEIP) { if (len != 0xFFFFU) do_forceip(&r, flag, p, len); return; }
    if (cmd == CMD_PACKETRESEND) {              /* never acknowledged (CR-201); extended ID only */
        if ((flag & GVCP_F_BCAST) && len != 0xFFFFU && len >= 20U)   /* bit 3 here = extended ID */
            gvsp_resend((uint8_t)rd16(p), ((uint64_t)rd32(p + 12) << 32) | rd32(p + 16), rd32(p + 4), rd32(p + 8));
        return;
    }

    if (is_primary(&r)) {
        s.last_rx = now_ms();                   /* heartbeat (R-075) */
        if (s.last_len != 0U && r.req_id == s.last_req) {   /* a retry: answer again, do not redo (R-051) */
            if (r.ack) send_to(&r.src, s.last_ack, s.last_len);
            return;
        }
    }
    if (len == 0xFFFFU || r.req_id == 0U) st = ST_INVALID_HEADER;
    else if (s.ccp == CCP_EA && !is_primary(&r)) st = ST_ACCESS_DENIED;   /* R-063 */
    else switch (cmd) {
        case CMD_READREG:  st = do_readreg(p, len, a + 8, &olen); break;
        case CMD_WRITEREG: st = do_writereg(&r, p, len, a + 8, &olen); break;
        case CMD_READMEM:  st = do_readmem(p, len, a + 8, &olen); break;
        case CMD_WRITEMEM: st = do_writemem(&r, p, len, a + 8, &olen); break;
        default:           st = ST_NOT_IMPLEMENTED; break;   /* R-132 */
    }
    ack_header(a, st, cmd, olen, r.req_id);
    if (r.ack) send_to(&r.src, a, 8U + olen);
    if (is_primary(&r)) {                       /* also the one that just took control */
        s.last_req = r.req_id;
        s.last_len = (uint16_t)(8U + olen);
        memcpy(s.last_ack, a, s.last_len);
        s.last_rx = now_ms();                   /* a long command does not eat the heartbeat (CR-212) */
    }
    if (s.reset_req) {
        printf("[GVCP] DeviceReset: SoC reset\r\n");
        vTaskDelay(pdMS_TO_TICKS(100));          /* let the ack leave (R-537) */
        watchdog_fatal(WD_CAUSE_REQUEST, 0, "GVCP DeviceReset");
    }
}

// StreamOverflow (EventSelector 0, design § 5.5) to the message channel, if open and the
// event is on: EVENT_CMD without an ack request, one 16 B standard event (GEV 2.2 § 16.7.1),
// device-specific id 0x9000, block id's low 16 bits, PLMT timestamp.
#define EVENT_STREAM_OVERFLOW   0x9000U
static void events_check(void)
{
    static uint16_t req = 0;
    struct sockaddr_in dst;
    uint8_t p[24];
    uint64_t bid;
    uint32_t hi, lo;
    uint8_t c;

    for (c = 0; c < SC_COUNT; ++c) {
        if (!gvsp_overflow_event(c, &bid)) continue;
        if (s.ccp == 0U || s.mcp == 0U || s.mcda == 0U || s.event_en[0] == 0U) continue;
        do {
            hi = DEV_PLMT->MTIME[1];
            lo = DEV_PLMT->MTIME[0];
        } while (hi != DEV_PLMT->MTIME[1]);
        if (++req == 0U) req = 1;
        p[0] = 0x42; p[1] = 0;
        wr16(p + 2, 0x00C0);
        wr16(p + 4, 16);
        wr16(p + 6, req);
        wr16(p + 8, 0);
        wr16(p + 10, EVENT_STREAM_OVERFLOW);
        wr16(p + 12, c);
        wr16(p + 14, (uint16_t)bid);
        wr32(p + 16, hi);
        wr32(p + 20, lo);
        memset(&dst, 0, sizeof(dst));
        dst.sin_family = AF_INET;
        dst.sin_addr.s_addr = htonl(s.mcda);
        dst.sin_port = htons((uint16_t)s.mcp);
        send_to(&dst, p, sizeof(p));
    }
}

static void heartbeat_check(void)
{
    if (s.ccp == 0U || (s.gvcp_cfg & CFG_HD)) return;
    if (now_ms() - s.last_rx > s.hb_ms) release("heartbeat expired");   /* R-076 */
}

static void state_init(void)
{
    uint32_t c;

    memset(&s, 0, sizeof(s));
    memset(&f, 0, sizeof(f));
    s.fd = -1;
    s.hb_ms = HB_DEFAULT_MS;
    s.mctt = 300;
    s.acq_count = 1;
    for (c = 0; c < SC_COUNT; ++c) s.scps[c] = SCPS_DEFAULT;
    for (c = 0; c < VIDEO_CAM_COUNT; ++c) {
        // Areascan by default (owner, 27.10.2026): any GigE Vision viewer shows frames at
        // once; profiles (Linescan3D) are switched on explicitly.
        s.scan_type[c] = GEV_SRC_OFF_DEVICE_SCAN_TYPE_AREASCAN;
        s.lines[c] = 1;
        s.comp_en[c][1] = 1;                    /* Range */
    }
    f.status = GEV_REG_FILE_OPERATION_STATUS_SUCCESS;
}

void task_gvcp_entry(void *pvParameters)
{
    static uint8_t rx[600];
    struct sockaddr_in bind_addr;
    int on = 1;
    (void)pvParameters;

    state_init();
    vTaskDelay(pdMS_TO_TICKS(3500));            /* the netif comes up after 3 s (task_console) */
    identity_init();
    s.fd = lwip_socket(AF_INET, SOCK_DGRAM, 0);
    if (s.fd < 0) {
        printf("[GVCP] socket failed: no GigE Vision control\r\n");
        vTaskDelete(NULL);
        return;
    }
    memset(&bind_addr, 0, sizeof(bind_addr));
    bind_addr.sin_family = AF_INET;
    bind_addr.sin_addr.s_addr = htonl(INADDR_ANY);
    bind_addr.sin_port = htons(GVCP_PORT);
    if (lwip_bind(s.fd, (struct sockaddr *)&bind_addr, sizeof(bind_addr)) < 0) {
        printf("[GVCP] bind %u failed: no GigE Vision control\r\n", (unsigned)GVCP_PORT);
        lwip_close(s.fd);
        vTaskDelete(NULL);
        return;
    }
    (void)lwip_setsockopt(s.fd, SOL_SOCKET, SO_BROADCAST, &on, sizeof(on));
    printf("[GVCP] GigE Vision control on UDP %u\r\n", (unsigned)GVCP_PORT);

    for (;;) {
        struct sockaddr_in src;
        socklen_t src_len = sizeof(src);
        struct timeval tv = { 0, 100000 };      /* heartbeat checked every 100 ms */
        fd_set rs;
        int n;

        FD_ZERO(&rs);
        FD_SET(s.fd, &rs);
        n = lwip_select(s.fd + 1, &rs, NULL, NULL, &tv);
        heartbeat_check();
        events_check();
        if (n <= 0) {
            if (n < 0) vTaskDelay(pdMS_TO_TICKS(20));
            continue;
        }
        n = lwip_recvfrom(s.fd, rx, sizeof(rx), 0, (struct sockaddr *)&src, &src_len);
        if (n > 0) handle(rx, n, &src);
    }
}
